function countOfPairs(nums) {
  const MOD = 1e9 + 7;
  const n = nums.length;
  const top = Math.max(...nums);
  const dp = Array.from({ length: n }, () => new Array(top + 1).fill(0));
  for (let value = 0; value <= nums[0]; value++) {
    dp[0][value] = 1;
  }
  for (let i = 1; i < n; i++) {
    const rise = Math.max(0, nums[i] - nums[i - 1]);
    let running = 0;
    for (let value = 0; value <= nums[i]; value++) {
      if (value - rise >= 0) {
        running = (running + dp[i - 1][value - rise]) % MOD;
      }
      dp[i][value] = running;
    }
  }
  let total = 0;
  for (let value = 0; value <= nums[n - 1]; value++) {
    total = (total + dp[n - 1][value]) % MOD;
  }
  return total;
}

