function countOfPairs(nums) {
  const MOD = 1000000007;
  const memo = new Map();
  // Ways to finish from index i when the previous parts were low (in arr1) and high (in arr2).
  const ways = (i, low, high) => {
    if (i === nums.length) return 1;
    const key = i + ',' + low + ',' + high;
    if (memo.has(key)) return memo.get(key);
    let count = 0;
    for (let a = 0; a <= nums[i]; a++) {
      const b = nums[i] - a;
      if (a >= low && b <= high) count = (count + ways(i + 1, a, b)) % MOD;
    }
    memo.set(key, count);
    return count;
  };
  return ways(0, 0, Infinity);
}

