function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 7);
    const top = int(1, 9);
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = int(1500, 2000);
  // Fully random values usually leave no valid pair at all.
  if (rand() < 0.2) return [Array.from({ length: n }, () => int(1, 50))];
  // Otherwise keep slack = value - (total forced rise of arr1) positive, so pairs exist.
  const nums = [];
  let value = int(20, 50);
  let slack = value;
  const dropRate = 0.002 + rand() * 0.01;
  const riseRate = 0.002 + rand() * 0.01;
  for (let i = 0; i < n; i++) {
    const roll = rand();
    if (roll < dropRate && slack > 1) {
      const drop = int(1, Math.min(3, slack - 1));
      value -= drop;
      slack -= drop;
    } else if (roll > 1 - riseRate && value < 50) {
      value += int(1, Math.min(3, 50 - value));
    }
    nums.push(value);
  }
  return [nums];
}
